When('the app is reloaded', function () {
  // Preserve localStorage across happy-dom window recreation
  var savedStorage = {};
  try {
    var storage = this.window.localStorage;
    for (var i = 0; i < storage.length; i++) {
      var key = storage.key(i);
      savedStorage[key] = storage.getItem(key);
    }
  } catch (e) { /* no storage yet */ }
  this.loadApp();
  try {
    var newStorage = this.window.localStorage;
    Object.keys(savedStorage).forEach(function (key) {
      newStorage.setItem(key, savedStorage[key]);
    });
  } catch (e) { /* ignore */ }
});

